class HafalatiApp extends StatefulWidget { @override _HafalatiAppState createState() => _HafalatiAppState(); }
class _HafalatiAppState extends State<HafalatiApp> {
  @override Widget build(BuildContext context) {
    return MaterialApp(debugShowCheckedModeBanner: false, title: 'Hafalati',
      theme: ThemeData(scaffoldBackgroundColor: AppConfig.black, primaryColor: AppConfig.gold, colorScheme: ColorScheme.dark(primary: AppConfig.gold, secondary: AppConfig.goldDark), appBarTheme: AppBarTheme(backgroundColor: AppConfig.black, foregroundColor: AppConfig.gold), elevatedButtonTheme: ElevatedButtonThemeData(style: ElevatedButton.styleFrom(backgroundColor: AppConfig.gold, foregroundColor: AppConfig.black))),
      home: InternetWrapper());
  }
}

class InternetWrapper extends StatefulWidget { @override _InternetWrapperState createState() => _InternetWrapperState(); }
class _InternetWrapperState extends State<InternetWrapper> {
  bool hasInternet = true; late StreamSubscription sub;
  @override void initState() { super.initState(); check(); sub = Connectivity().onConnectivityChanged.listen((r) { setState(() => hasInternet = r != ConnectivityResult.none); }); }
  void check() async { var c = await Connectivity().checkConnectivity(); setState(() => hasInternet = c != ConnectivityResult.none); }
  @override void dispose() { sub.cancel(); super.dispose(); }
  @override Widget build(BuildContext context) {
    if (!hasInternet) { return Scaffold(backgroundColor: AppConfig.black, body: Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(Icons.wifi_off, size: 80, color: AppConfig.gold), SizedBox(height: 20), Text(AppLang.tr('noInternet'), style: TextStyle(color: AppConfig.gold, fontSize: 18)), SizedBox(height: 20), ElevatedButton(onPressed: check, child: Text('إعادة المحاولة'))]))); }
    return AuthGate();
  }
}

class AuthGate extends StatelessWidget { @override Widget build(BuildContext context) { return StreamBuilder<User?>(stream: FirebaseAuth.instance.authStateChanges(), builder: (c, snap) { if (snap.connectionState == ConnectionState.waiting) return Scaffold(body: Center(child: CircularProgressIndicator(color: AppConfig.gold))); if (snap.hasData) return MainScreen(user: snap.data!); return LoginScreen(); }); } }

class LoginScreen extends StatefulWidget { @override _LoginScreenState createState() => _LoginScreenState(); }
class _LoginScreenState extends State<LoginScreen> {
  final emailC = TextEditingController(); final passC = TextEditingController(); final nameC = TextEditingController(); bool isLogin = true; bool loading = false;
  void submit() async { setState(() => loading = true); try { if (isLogin) { await FirebaseAuth.instance.signInWithEmailAndPassword(email: emailC.text.trim(), password: passC.text.trim()); } else { var cred = await FirebaseAuth.instance.createUserWithEmailAndPassword(email: emailC.text.trim(), password: passC.text.trim()); await FirebaseFirestore.instance.collection('users').doc(cred.user!.uid).set({'name': nameC.text.trim(),'email': emailC.text.trim(),'coins': 0,'level': 1,'totalDeposit': 0,'createdAt': FieldValue.serverTimestamp(),'isBand': false}); } } catch (e) { ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString()))); } setState(() => loading = false); }
  @override Widget build(BuildContext context) { return Scaffold(backgroundColor: AppConfig.black, body: Padding(padding: EdgeInsets.all(24), child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(Icons.celebration, size: 80, color: AppConfig.gold), SizedBox(height: 10), Text(AppLang.tr('appName'), style: TextStyle(fontSize: 32, fontWeight: FontWeight.bold, color: AppConfig.gold)), SizedBox(height: 30), if (!isLogin) TextField(controller: nameC, style: TextStyle(color: Colors.white), decoration: InputDecoration(labelText: 'الاسم الكامل', labelStyle: TextStyle(color: AppConfig.gold), enabledBorder: OutlineInputBorder(borderSide: BorderSide(color: AppConfig.gold)))), if (!isLogin) SizedBox(height: 12), TextField(controller: emailC, style: TextStyle(color: Colors.white), decoration: InputDecoration(labelText: AppLang.tr('email'), labelStyle: TextStyle(color: AppConfig.gold), enabledBorder: OutlineInputBorder(borderSide: BorderSide(color: AppConfig.gold)))), SizedBox(height: 12), TextField(controller: passC, obscureText: true, style: TextStyle(color: Colors.white), decoration: InputDecoration(labelText: AppLang.tr('password'), labelStyle: TextStyle(color: AppConfig.gold), enabledBorder: OutlineInputBorder(borderSide: BorderSide(color: AppConfig.gold)))), SizedBox(height: 20), loading ? CircularProgressIndicator(color: AppConfig.gold) : ElevatedButton(onPressed: submit, child: Text(isLogin ? AppLang.tr('login') : AppLang.tr('register')), style: ElevatedButton.styleFrom(minimumSize: Size(double.infinity, 50))), TextButton(onPressed: () => setState(() => isLogin = !isLogin), child: Text(isLogin ? 'ما عندكش حساب؟ إنشاء حساب جديد' : 'عندك حساب؟ تسجيل الدخول', style: TextStyle(color: AppConfig.gold)))]))); }
}

